#!/bin/bash
set -e
echo '[pathctl] install: writing project files'

cat > package.json << 'EOF'
{
  "name": "rdk-path-control",
  "version": "1.0.1",
  "description": "RDK SD-WAN path control over IoT Core (plain mqtt)",
  "main": "index.js",
  "license": "ISC"
}
EOF

cat > index.js << 'EOF'
const fs = require('fs');
const axios = require('axios');
const mqtt = require('mqtt');

// Config injected by the Run lifecycle as env vars (see Setenv). Defaults are
// the standard Greengrass v2 cert paths + the account IoT endpoint.
const PREFIX    = process.env.PATHCTL_TOPIC_PREFIX || 'rdk';
const LOCAL_API = process.env.PATHCTL_LOCAL_API   || 'http://127.0.0.1:8090/api/path';
const ENDPOINT  = process.env.PATHCTL_IOT_ENDPOINT || 'alht1i2bx8tzt-ats.iot.us-east-1.amazonaws.com';
const CERT_PATH = process.env.PATHCTL_CERT || '/greengrass/v2/thingCert.crt';
const KEY_PATH  = process.env.PATHCTL_KEY  || '/greengrass/v2/privKey.key';
const CA_PATH   = process.env.PATHCTL_CA   || '/greengrass/v2/rootCA.pem';
const CONTROL_TOPIC = PREFIX + '/path/control';
const RESULT_TOPIC  = PREFIX + '/path/control/result';
const VALID_MODES   = ['auto', 'fiber', '5g'];

let cert, key, ca;
try {
  cert = fs.readFileSync(CERT_PATH);
  key  = fs.readFileSync(KEY_PATH);
  ca   = fs.readFileSync(CA_PATH);
} catch (e) {
  console.error('[pathctl] FATAL: cannot read device certs:', e && e.message);
  console.error('[pathctl] check certPath/keyPath/caPath in component config; current:', CERT_PATH, KEY_PATH, CA_PATH);
  process.exit(1);
}

const client = mqtt.connect({
  host: ENDPOINT,
  port: 8883,
  protocol: 'mqtts',
  clientId: 'pathctl-' + PREFIX + '-' + Math.random().toString(36).slice(2, 10),
  cert: cert,
  key: key,
  ca: ca,
  reconnectPeriod: 3000,
  keepalive: 30,
  rejectUnauthorized: true,
});

function publishResult(body) {
  const payload = JSON.stringify(Object.assign({}, body, { ts: Date.now() }));
  client.publish(RESULT_TOPIC, payload, { qos: 1 });
  console.log('[pathctl] result:', payload);
}

client.on('connect', () => {
  console.log('[pathctl] connected to ' + ENDPOINT + '; control=' + CONTROL_TOPIC + ' result=' + RESULT_TOPIC);
  client.subscribe(CONTROL_TOPIC, { qos: 1 }, (err) => {
    if (err) console.error('[pathctl] subscribe failed:', err.message);
    else console.log('[pathctl] subscribed; waiting for commands');
  });
});
client.on('error', (e) => console.error('[pathctl] mqtt error:', e && e.message));
client.on('reconnect', () => console.log('[pathctl] reconnecting...'));
client.on('close', () => console.log('[pathctl] connection closed'));

client.on('message', async (topic, payload) => {
  const raw = payload.toString('utf-8');
  console.log('[pathctl] command received on ' + topic + ': ' + raw);
  let mode, id;
  try { const p = JSON.parse(raw); mode = p.mode; id = p.id; }
  catch { publishResult({ ok: false, error: 'invalid JSON payload' }); return; }
  if (!VALID_MODES.includes(mode)) {
    publishResult({ id: id, ok: false, error: 'mode must be one of auto|fiber|5g', got: mode });
    return;
  }
  try {
    const res = await axios.post(LOCAL_API, { mode: mode }, { timeout: 5000, headers: { 'Content-Type': 'application/json' } });
    publishResult({ id: id, ok: true, mode: mode, httpStatus: res.status });
  } catch (e) {
    const status = e && e.response ? e.response.status : null;
    publishResult({ id: id, ok: false, mode: mode, httpStatus: status, error: e && e.message });
  }
});

// Keep the event loop alive for the lifetime of the component.
setInterval(() => {}, 1 << 30);
EOF

echo '[pathctl] install: npm install (pure JS deps)'
npm install mqtt axios --cache /tmp/npm-cache --omit=dev
echo '[pathctl] install: done'
